BEGIN TRANSACTION;
CREATE TABLE automatic_decisions (decision_id TEXT PRIMARY KEY NOT NULL CHECK(decision_id GLOB 'automatic_decision_[0-9a-f]*' AND length(decision_id)=83), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), destination TEXT NOT NULL CHECK(length(destination) BETWEEN 1 AND 64), idempotency_digest TEXT NOT NULL UNIQUE CHECK(length(idempotency_digest)=64 AND idempotency_digest NOT GLOB '*[^0-9a-f]*'), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 65536), UNIQUE(review_case_id,destination));
CREATE TABLE automatic_safety_state (singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1), paused INTEGER NOT NULL CHECK(paused IN (0,1)), global_suspension TEXT, category_suspensions_document TEXT NOT NULL, updated_at INTEGER NOT NULL CHECK(updated_at>=0));
INSERT INTO "automatic_safety_state" VALUES(1,0,NULL,'[]',0);
CREATE TABLE cover_consideration_events (event_id TEXT PRIMARY KEY NOT NULL CHECK(event_id GLOB 'cover_consideration_event_[0-9a-f]*' AND length(event_id)=90), consideration_id TEXT NOT NULL REFERENCES cover_considerations(consideration_id), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), kind TEXT NOT NULL CHECK(kind IN ('automatic_prepared','owner_retry_prepared','superseded','selected','kept_incumbent','no_action','stale')), decision_id TEXT, occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096));
CREATE TABLE cover_considerations (consideration_id TEXT PRIMARY KEY NOT NULL CHECK(consideration_id GLOB 'cover_consideration_[0-9a-f]*' AND length(consideration_id)=84), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), replay_digest TEXT NOT NULL CHECK(length(replay_digest)=64 AND replay_digest NOT GLOB '*[^0-9a-f]*'), document_digest TEXT NOT NULL CHECK(length(document_digest)=64 AND document_digest NOT GLOB '*[^0-9a-f]*'), supersedes_id TEXT REFERENCES cover_considerations(consideration_id), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), currentness_document TEXT NOT NULL CHECK(typeof(currentness_document)='text' AND length(CAST(currentness_document AS BLOB)) BETWEEN 4 AND 4096), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 12582912));
CREATE TABLE cover_selection_authorities (selection_id TEXT PRIMARY KEY NOT NULL CHECK(typeof(selection_id)='text' AND selection_id GLOB 'cover_selection_[0-9a-f]*' AND length(selection_id)=80), connection_name TEXT NOT NULL CHECK(typeof(connection_name)='text' AND length(CAST(connection_name AS BLOB)) BETWEEN 1 AND 128), library_name TEXT NOT NULL CHECK(typeof(library_name)='text' AND length(CAST(library_name AS BLOB)) BETWEEN 1 AND 128), item_id TEXT NOT NULL CHECK(typeof(item_id)='text' AND length(CAST(item_id AS BLOB)) BETWEEN 1 AND 512), kind TEXT NOT NULL CHECK(kind IN ('automatic','owner')), decision_id TEXT NOT NULL UNIQUE CHECK((kind='automatic' AND decision_id GLOB 'automatic_decision_[0-9a-f]*' AND length(decision_id)=83) OR (kind='owner' AND decision_id GLOB 'human_decision_[0-9a-f]*' AND length(decision_id)=79)), consideration_id TEXT NOT NULL REFERENCES cover_considerations(consideration_id), supersedes_selection_id TEXT REFERENCES cover_selection_authorities(selection_id), occurred_at INTEGER NOT NULL CHECK(typeof(occurred_at)='integer' AND occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 131072), CHECK(supersedes_selection_id IS NULL OR supersedes_selection_id<>selection_id));
CREATE TABLE current_cover_considerations (review_case_id TEXT PRIMARY KEY NOT NULL REFERENCES review_cases(review_case_id), consideration_id TEXT NOT NULL UNIQUE REFERENCES cover_considerations(consideration_id));
CREATE TABLE current_cover_selection_authorities (connection_name TEXT NOT NULL CHECK(typeof(connection_name)='text' AND length(CAST(connection_name AS BLOB)) BETWEEN 1 AND 128), library_name TEXT NOT NULL CHECK(typeof(library_name)='text' AND length(CAST(library_name AS BLOB)) BETWEEN 1 AND 128), item_id TEXT NOT NULL CHECK(typeof(item_id)='text' AND length(CAST(item_id AS BLOB)) BETWEEN 1 AND 512), selection_id TEXT NOT NULL UNIQUE REFERENCES cover_selection_authorities(selection_id), PRIMARY KEY(connection_name,library_name,item_id));
CREATE TABLE current_description_advice (review_case_id TEXT PRIMARY KEY NOT NULL REFERENCES review_cases(review_case_id), attempt_id TEXT NOT NULL REFERENCES description_advice_attempts(attempt_id), candidate_id TEXT REFERENCES description_advice_candidates(candidate_id), binding_document TEXT NOT NULL CHECK(length(CAST(binding_document AS BLOB)) BETWEEN 2 AND 4096));
CREATE TABLE current_description_decisions (review_case_id TEXT PRIMARY KEY NOT NULL REFERENCES review_cases(review_case_id), decision_id TEXT NOT NULL REFERENCES description_decisions(decision_id));
CREATE TABLE current_metadata_report_lineages (connection_name TEXT NOT NULL, library_name TEXT NOT NULL, item_id TEXT NOT NULL, report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), PRIMARY KEY (connection_name, library_name, item_id));
